INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1900420507292012544, 1798176607609950208, 'uBVoZXNhCXXbFcqyfVqRK', '基努·李维斯在电影《康斯坦丁》中饰演的角色名叫约翰·康斯坦丁（John Constantine）。这个角色源自DC漫画《地狱神探》（Hellblazer），约翰·康斯坦丁是漫画中的主角，一个擅长驱魔和对抗超自然力量的魔法师。电影沿用了漫画中的角色设定，因此基努·李维斯的角色名字为约翰。这个名字是为了忠实于原著漫画的角色背景和设定。', 'f', '2025-03-14 13:35:31.701658', 'admin', '2025-03-14 13:35:31.701658', 'admin');
