INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1827957222819368960, 1798176607609950208, 'CatPm4sHTc_tJKCdKZITC', '马龙被称为“六边形战士”是因为他在乒乓球领域的全面能力，即在技术、战术、心理、体能、速度和力量等方面都表现出色，形成了一个近乎完美的六边形。这种称呼是对他全面能力的赞誉。', 'f', '2024-08-26 14:32:18.380191', 'qinyuanpei', '2024-08-26 14:32:18.380191', 'qinyuanpei');
