INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1784762337522225152, 1772861261323833345, 'Z-XgdtSVGWJyVgtyoSXoo', '鲍德温三世是耶路撒冷的国王，他在侄子鲍德温四世出生时主持了洗礼仪式，并将自己名字作为礼物赠送给新生儿。在大臣开玩笑提出仅赠送名字作为礼物显得吝啬时，鲍德温三世指着圣十字架表示再送一份礼物，即耶路撒冷之王的称号。鲍德温三世后来突然患上重病，因为他没有子女，所以王位由他的侄子鲍德温四世继承，成为新一任的国王。', 'f', '2024-04-29 09:51:15.203105', 'admin', '2024-04-29 09:51:15.203105', 'admin');
