INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1825723424979423232, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '周杰伦（Jay Chou），1979年1月18日出生于台湾省新北市，祖籍福建省永春县，是一位华语流行乐男歌手、音乐人、演员、导演、编剧，毕业于淡江中学。他于2000年发行了个人首张音乐专辑《Jay》，并在2001年凭借专辑《范特西》奠定了其融合中西方音乐的风格。周杰伦的音乐作品广受欢迎，包括《爱在西元前》和《一路向北 (Bonus Track)》等。', 'f', '2024-08-20 10:35:59.458356', 'admin', '2024-08-20 10:35:59.458356', 'admin');
