INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1825729000136380416, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '许昕是一位非常全面的乒乓球运动员，出生于1990年1月8日，江苏省徐州市。他是中国男子乒乓球队的一员，并在多个重要赛事中取得了显著成就，包括2010年广州亚运会。他还被列入国际乒联名人堂，这进一步证明了他的全面性和在乒乓球领域的卓越表现。', 'f', '2024-08-20 10:58:08.68156', 'admin', '2024-08-20 10:58:08.68156', 'admin');
