INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1787669103683702784, 1772861261323833345, 'oOaZamtRAKVCeBJnv88jG', '郭靖是中国著名作家金庸（Louis Cha）创作的武侠小说《射雕英雄传》中的主角。他是一位正直、忠诚、勇敢且有强烈正义感的武林高手。在故事中，郭靖经历了许多冒险和挑战，逐渐成长为一名武林领袖，并且与黄蓉、杨康等人物建立了深厚的关系。他的形象深受读者喜爱，成为了中国武侠文化中的一个标志性人物。', 'f', '2024-05-07 10:21:42.261426', 'admin', '2024-05-07 10:21:42.261426', 'admin');
