INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1787669498912968704, 1772861261323833345, 'oOaZamtRAKVCeBJnv88jG', '郭靖是中国著名武侠小说家金庸（原名查良镛）所著的武侠小说《射雕英雄传》中的主人公。他以其正直、忠诚、勇敢的品质以及卓越的武艺而著称。在小说中，郭靖是江湖上的一位英雄人物，深受读者喜爱，并且在中国武侠文化中占有重要地位。', 'f', '2024-05-07 10:23:16.491248', 'admin', '2024-05-07 10:23:16.491248', 'admin');
