INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1797818140139327488, 1772861261323833344, 'IKWvdRASUiZrGZUDCC33Z', 'Phishing 是一种欺诈性行为，其目的是在网络通信中伪装成一些值得信赖的实体，以企图获取敏感信息。这通常包括用户名、密码、信用卡细节以及其他可以导致身份盗窃或金融损失的个人信息。攻击者会利用诈骗邮件、假冒网站、社交媒体平台等手段，诱导用户不经意间提供他们的敏感信息。这本距离常包括设置陷阱，如发送含有恶意链接或附件的电子邮件，要求用户输入个人信息来“确认”或“更新”他们的账户信息，从而达到不法的目的。', 'f', '2024-06-04 10:30:21.103072', 'admin', '2024-06-04 10:30:21.103072', 'admin');
