INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1798171146747777024, 1772861261323833344, 'IKWvdRASUiZrGZUDCC33Z', '"有朋自远方来"是中国古代儒家经典《论语》中的一句话，出自《论语·学而》篇。这句话的完整内容是：“有朋自远方来，不亦乐乎？”意思是说，有朋友从远方来访，是一件非常快乐的事情。这句话体现了孔子对友情的重视，以及对朋友相聚的欢愉之情。', 'f', '2024-06-05 09:53:04.445175', 'admin', '2024-06-05 09:53:04.445175', 'admin');
