INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1805857070306693120, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '- 许嵩，出生于1986年5月14日，是一位中国内地的流行乐男歌手、词曲作者、编曲、音乐人。他毕业于安徽医科大学，大学期间自修作曲及音乐制作，并通过博客发表音乐作品。2009年，他独立出版了首张词曲全创作专辑。目前，许嵩担任海蝶音乐公司（现为太合音乐集团）的音乐总监。', 'f', '2024-06-26 14:54:11.4202', 'admin', '2024-06-26 14:54:11.4202', 'admin');
