INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1825465821317697536, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '马龙，1988年10月20日出生于辽宁省鞍山市，是中国著名的乒乓球运动员，现任中国乒乓男队队长。他是乒乓球史上首位集奥运会、世锦赛、世界杯、亚运会、亚锦赛、亚洲杯、巡回赛总决赛、全运会及全锦赛单打冠军于一身的“超级全满贯”男子选手。马龙拥有5枚奥运金牌，是所有运动员中最多的，其历史印记已经得到巩固。此外，他还是乒乓球史上首位成功蝉联奥运会男单金牌及拥有最多奥运金牌（六金）的乒乓球员。', 'f', '2024-08-19 17:32:21.974441', 'qinyuanpei', '2024-08-19 17:32:21.974441', 'qinyuanpei');
