INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1807691163340247040, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '姜维在蜀汉灭亡前的最后一次军事行动中，试图通过派遣部队前往魏国边境制造混乱，以分散魏军的注意力。虽然这一计策最终没有取得预期的效果，但展现了姜维的勇气和决心。在临终前，姜维还写下了一篇《后出师表》，表达了对国家和民族的忠诚和热爱。姜维的结局体现了他的忠诚和勇敢，尽管面对不可逆转的局势，他依然坚持自己的信念和职责。', 'f', '2024-07-01 16:22:13.275187', 'admin', '2024-07-01 16:22:13.275187', 'admin');
