INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1808316332194795520, 1798176607609950208, 'iueg-iLfuqNyk76ZMdJlB', '元培学院是北京大学的一个学院，致力于提供通识教育和跨学科专业，允许学生在全校范围内自由选择专业和课程。学院的特色包括自由选择专业与课程、特色跨学科专业、前瞻性课程体系、弹性学习年限、通识教育基础课、入学教育、全方位导师制和住宿书院等。元培学院的目标是培养具有国际视野、创新精神和实践能力的高素质领军人才。', 'f', '2024-07-03 09:46:25.145551', 'admin', '2024-07-03 09:46:25.145551', 'admin');
