INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1808779330277478400, 1798176607609950208, 'HnFL4ab6gKMA2OI7_j-LE', '苏州当前的天气是晴天，气温高达37.0摄氏度，湿度为46%，西南风3级，风速5.2米/秒。未来几天主要以晴朗或多云为主，气温保持在36至36.6摄氏度。但需注意7月9日和10日可能会有小雨和中雨，届时气温将略有下降。', 'f', '2024-07-04 16:26:12.490554', 'admin', '2024-07-04 16:26:12.490554', 'admin');
