INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1808781669419847680, 1798176607609950208, 'HnFL4ab6gKMA2OI7_j-LE', '明天中卫的天气预报是多云，白天最高温度为30°C，夜间最低温度为18°C，风向为无持续风向，风力为微风。请注意，中卫市气象台已发布雷电黄色预警信号，建议公众注意防雷并尽量避免户外活动。', 'f', '2024-07-04 16:35:30.184596', 'admin', '2024-07-04 16:35:30.184596', 'admin');
