INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1809027220824526848, 1798176607609950208, 'HnFL4ab6gKMA2OI7_j-LE', '罗翔老师和张三的关系是：罗翔老师在讲解法律案例时经常使用“张三”作为虚拟人物来举例，这个角色在案例中扮演了多种角色，因此被网友戏称为“法外狂徒张三”。罗翔老师通过这种方式，以幽默风趣的方式普及法律知识，赢得了广泛的喜爱和关注。', 'f', '2024-07-05 08:51:14.201434', 'admin', '2024-07-05 08:51:14.201434', 'admin');
