INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1809050616987783168, 1798176607609950208, 'HnFL4ab6gKMA2OI7_j-LE', '"Happy Friday" 通常是指人们庆祝一周工作结束和周末开始的积极情绪表达。这个词可能起源于夏威夷群岛，作为一种庆祝周五到来的积极问候方式。然而，在不同的文化和宗教背景下，周五可能有不同的含义，例如在基督教中，Good Friday 是一个纪念耶稣受难的严肃日子。', 'f', '2024-07-05 10:24:12.281692', 'admin', '2024-07-05 10:24:12.281692', 'admin');
