INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1822882246810537984, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '《死侍与金刚狼》最新的票房信息如下：
