INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1810157993753448448, 1798176607609950208, 'O0dU_i5bW2SPRlk4M023g', '根据最新的财经报道，2023年贵州茅台的系列酒实现营业收入206.29亿元，首次突破两百亿大关，显示出强劲的增长势头。此外，公司还计划分红近388亿，创下新高。这些数据表明茅台酒在过去一个月内的销售情况非常良好，且市场对其产品的需求持续旺盛。同时，茅台酒的出厂价上调和年份酒价格的变动也反映了市场动态和消费者需求的变化。', 'f', '2024-07-08 11:44:31.476933', 'admin', '2024-07-08 11:44:31.476933', 'admin');
