INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1810488055300231168, 1798176607609950208, 'O0dU_i5bW2SPRlk4M023g', '金凯瑞的电影中他饰演的角色婚姻通常都非常失败，这可能是因为他的电影主题和角色设定往往包含超现实幽默和讽刺元素，这些元素可能导致角色的婚姻关系出现问题。此外，金凯瑞的角色经常面临生活中的困境和挑战，这也可能影响了他们的婚姻关系。', 'f', '2024-07-09 09:36:04.282092', 'admin', '2024-07-09 09:36:04.282092', 'admin');
