INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1810522976987254784, 1798176607609950208, 'O0dU_i5bW2SPRlk4M023g', 'GraphRAG的核心设计是利用大型语言模型（LLMs）和知识图谱（knowledge graphs）来增强传统的检索增强生成（RAG）方法。它通过模块化的架构设计，允许用户根据特定需求定制和扩展系统功能，从而从非结构化文本中提取有意义的结构化数据。这种设计不仅提升了系统的性能，还增强了其灵活性和可扩展性。', 'f', '2024-07-09 11:54:50.261587', 'admin', '2024-07-09 11:54:50.261587', 'admin');
