INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1810560378049007616, 1798176607609950208, 'O0dU_i5bW2SPRlk4M023g', '郭靖学过的武功包括九阴真经、降龙十八掌、七十二路空明拳、双手互搏等多种上乘武学。他的武功修为在《射雕英雄传》和《神雕侠侣》中不断提升，最终成为当世武功绝顶的高手。郭靖的结局是在襄阳城失陷时，与妻子黄蓉和儿子郭破虜一同殉国，体现了其“为国为民，侠之大者”的精神。', 'f', '2024-07-09 14:23:27.369275', 'admin', '2024-07-09 14:23:27.369275', 'admin');
