INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811314836009783296, 1798176607609950208, 'jEoa8riznjZ2LDjx3s_xn', '李连杰是一位出生于中国北京市的新加坡籍武术家、演员、导演和制片人。他因在多部武术电影中的出色表现而闻名，包括《少林寺》、《黄飞鸿》系列和《笑傲江湖2：东方不败》等。李连杰近年来对待生死看得很淡，已向妻子利智交代了身后事，表示一切从简。', 'f', '2024-07-11 16:21:24.164344', 'admin', '2024-07-11 16:21:24.164344', 'admin');
