INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811315335798853632, 1798176607609950208, 'jEoa8riznjZ2LDjx3s_xn', '许嵩是一位多才多艺的中国内地流行乐男歌手、词曲作者、编曲、音乐人，现任太合音乐集团音乐总监。他出生于1986年5月14日，毕业于安徽医科大学。自2006年起，许嵩开始发表音乐作品，并已成功发行多张个人原创专辑和单曲，其中包括《雅俗共赏》、《有何不可》、《素颜》等经典歌曲。', 'f', '2024-07-11 16:23:23.323682', 'admin', '2024-07-11 16:23:23.323682', 'admin');
