INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811315681082347520, 1798176607609950208, 'jEoa8riznjZ2LDjx3s_xn', '黄益贺是一位专注于AI技术和内容创作的活跃社交媒体用户。他在哔哩哔哩和抖音等平台上分享视频和动态，内容涉及AI技术的本地化应用和相关资讯。他还在知识星球社群中分享AI资讯，强调内容和代码的重要性，并鼓励人们成为“超级个体”。通过这些平台，黄益贺积极推广AI知识，并与关注者互动，分享他的见解和经验。', 'f', '2024-07-11 16:24:45.64529', 'admin', '2024-07-11 16:24:45.64529', 'admin');
