INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811316617834008576, 1798176607609950208, 'jEoa8riznjZ2LDjx3s_xn', '《食南之徒》主要讲了什么故事，结局如何', 't', '2024-07-11 16:28:28.984055', 'admin', '2024-07-11 16:28:28.984055', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811317001361166336, 1798176607609950208, 'jEoa8riznjZ2LDjx3s_xn', '《食南之徒》主要讲述了汉武帝时期，美食爱好者唐蒙出使南越国，卷入南越王赵佗之死的调查，揭示了南越国与大汉朝之间的复杂关系。故事中的人物在热爱中寻找真谛，对待食物至纯至真，同时也展现了人物的坚持和道义。结局方面，故事在层层递进后推向高潮，可能涉及一些历史事件的解决和人物命运的转折。', 'f', '2024-07-11 16:30:00.424039', 'admin', '2024-07-11 16:30:00.424039', 'admin');
