INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1818162500219310080, 1772861261323833345, 'Z-XgdtSVGWJyVgtyoSXoo', '宫崎骏的作品包括《红猪》、《风之谷》、《天空之城》、《哈尔的移动城堡》、《龙猫》、《千与千寻》等。这些作品以其精美的画面和深刻的主题受到全球观众的喜爱。', 'f', '2024-07-30 13:51:34.535077', 'qinyuanpei', '2024-07-30 13:51:34.535077', 'qinyuanpei');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811317957352099840, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '马伯庸，原名马力，1980年出生于内蒙古自治区赤峰市，是中国当代著名作家和编剧。他是中国作家协会会员、文学创作一级，同时也是南京大学文学院的兼职教授。马伯庸的作品广泛涉及历史、科幻、影视评论等多个领域，以其独特的文风和深入的历史研究而受到读者的喜爱。他的代表作品包括《风起陇西》、《长安十二时辰》、《显微镜下的大明》等，这些作品不仅在文学界获得了高度评价，也被改编成电视剧和电影，进一步扩大了他的影响力。', 'f', '2024-07-11 16:33:48.349876', 'admin', '2024-07-11 16:33:48.349876', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811319058197516288, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '如何评价张若昀在《庆余年》中的表演', 't', '2024-07-11 16:38:10.797368', 'admin', '2024-07-11 16:38:10.797368', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811319140686893056, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '张若昀在《庆余年》中的表演受到了观众和评论界的一致好评。他成功地塑造了一个既机智又深情的范闲，无论是角色的内心戏还是外在的行动，都展现出了高水平的演技。他的表演不仅丰富了角色的层次，也为剧情增添了更多的看点，使得《庆余年》成为了一部深受观众喜爱的作品。', 'f', '2024-07-11 16:38:30.478719', 'admin', '2024-07-11 16:38:30.478719', 'admin');
