INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811335439462830080, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '黄梅天苹果上长出的蘑菇实际上是一种名为裂褶菌（白参）的食用菌，通常生长在腐木上。这种蘑菇无毒，可以食用，并且具有一定的科研价值。这种现象可能是由于黄梅天的高湿度和适宜温度，加上苹果可能接触到了蘑菇的孢子，从而导致了蘑菇的生长。', 'f', '2024-07-11 17:43:16.410062', 'admin', '2024-07-11 17:43:16.410062', 'admin');
