INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811335841910493184, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '中国U15国少队在2024年7月11日与韩国U15国少队的第二场热身赛中以4比1获胜。这场比赛中，中国小将在下半场连进三球，成功逆转并战胜了韩国队。这场胜利对中国足球小将的信心和士气有着极大的鼓舞作用，也预示着中国足球未来的希望。', 'f', '2024-07-11 17:44:52.361304', 'admin', '2024-07-11 17:44:52.361304', 'admin');
