INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811336209138585600, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', 'The blue-blooded creatures spotted in Shenzhen Bay are likely Chinese horseshoe crabs (鲎), a species known for its blue blood due to the presence of copper-based hemocyanin in its bloodstream. These creatures are of significant medical importance as their blood is used in the Limulus amebocyte lysate (LAL) test to detect bacterial endotoxins. However, their populations are declining due to overfishing and habitat destruction, highlighting the need for conservation efforts to protect these ancient and unique species.', 'f', '2024-07-11 17:46:19.915602', 'admin', '2024-07-11 17:46:19.915602', 'admin');
