INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811339563185082368, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '雷军的《Are You OK》是一首网络流行歌曲，起源于他在2015年印度小米手机4i发布会上用英语问候观众时说的“Are you OK？”这句话。由于雷军的英语发音带有浓厚的中文口音，这句话迅速在网络上走红，并被网友改编成歌曲。这首歌在B站上非常受欢迎，雷军本人也在后续的演讲中幽默地回顾了这一现象。', 'f', '2024-07-11 17:59:39.555819', 'admin', '2024-07-11 17:59:39.555819', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811339759986020352, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '雷军', 't', '2024-07-11 18:00:26.502873', 'admin', '2024-07-11 18:00:26.502873', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811339840952864768, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '雷军是一位出生于1969年的中国企业家，以小米科技的创始人和董事长身份最为人所知。他毕业于武汉大学，并在科技行业拥有超过30年的经验。雷军不仅在商业上取得了巨大成功，还积极参与政治和社会活动，如担任全国人民代表大会代表和民间商会副会长。他的职业生涯展示了他在创新和领导力方面的卓越能力，尤其是在推动小米成为全球知名的科技品牌方面。', 'f', '2024-07-11 18:00:45.807633', 'admin', '2024-07-11 18:00:45.807633', 'admin');
