INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811341293188681728, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '安妮·海瑟薇是一位出生于1982年11月12日的美国女演员，自1999年出道以来，她在《公主日记》、《穿普拉达的女魔头》、《蕾切尔的婚礼》、《蝙蝠侠：黑暗骑士》、《爱情与灵药》和《星际穿越》等多部电影中展现了她的演技。她因其多样的角色和出色的表演而受到广泛赞誉，并继续在演艺事业上取得成功。', 'f', '2024-07-11 18:06:31.999121', 'admin', '2024-07-11 18:06:31.999121', 'admin');
