INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811341634051379200, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '《Are You OK》是一首源自雷军在印度小米4i发布会上的一段演讲的网络流行歌曲。这段演讲因其独特的风格被B站UP主制作成鬼畜视频，迅速在网络上走红，成为一种文化现象。雷军本人对此持开放态度，这首歌也成为了他的个人标签，展现了他的幽默感和对网络文化的接纳。这首歌的流行不仅反映了雷军的个人影响力，也体现了当代网络文化的特点。', 'f', '2024-07-11 18:07:53.315534', 'admin', '2024-07-11 18:07:53.315534', 'admin');
