INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1811579739555631104, 1798176607609950208, 'QFEV33c4wAcNdtL-vmG_W', '安妮·海瑟薇是一位多才多艺的美国女演员，出生于1982年11月12日。她以其多样化的角色和出色的表演技巧在电影和电视界取得了显著的成就。从她的早期作品《公主日记》到后来的《穿普拉达的女王》和《爱情与灵药》，安妮·海瑟薇展现了她作为演员的广泛才能和深厚的演技。她的作品不仅在美国国内受到欢迎，也在全球范围内赢得了观众的喜爱和认可。', 'f', '2024-07-12 09:54:02.09067', 'qinyuanpei', '2024-07-12 09:54:02.09067', 'qinyuanpei');
