INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1813093730878623744, 1798176607609950208, 'adltLYOXnYIrexIV-1yCW', '张艺谋，1950年4月2日出生于陕西省西安市，是中国电影导演，“第五代导演”代表人物之一，曾获得美国波士顿大学和耶鲁大学荣誉博士学位。他不仅在电影领域有显著成就，还涉足实业家、编剧和演员等多个领域。张艺谋的个人生活也颇受关注，如“张艺谋超生门”事件。此外，他还参与了多部作品的创作，并有多部关于他的传记和研究书籍出版。', 'f', '2024-07-16 14:10:05.751579', 'admin', '2024-07-16 14:10:05.751579', 'admin');
