INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1813094975760633856, 1798176607609950208, 'adltLYOXnYIrexIV-1yCW', '李彦宏（Robin Li），男，汉族，无党派人士，1968年11月出生，山西阳泉人。他是百度公司创始人，曾被《时代周刊》报道，与北京大学有紧密联系，并因其超链分析技术而知名。李彦宏被认为是工程师、实业家和作家。他还设立了北京大学“李彦宏回报基金”，用于支持教育项目。', 'f', '2024-07-16 14:15:02.554249', 'admin', '2024-07-16 14:15:02.554249', 'admin');
