INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1814135870958211072, 1798176607609950208, 'adltLYOXnYIrexIV-1yCW', '《神探夏洛克》第五季的剧情构思非常吸引人，将围绕一个涉及人工智能网络攻击的复杂案件展开。本季将通过多个场景深入描绘夏洛克与华生之间的关系，并展示他们在高科技犯罪面前的合作与冲突。同时，剧中将引入一位前科技公司的首席技术官作为主要反派，他的技术专长和对现代社会的深刻理解使他成为一个极具挑战性的对手。此外，剧情还将探讨现代科技对人们日常生活的影响，特别是关于隐私权和数据安全的重要性。这样的剧情设计不仅保持了剧集原有的推理悬疑风格，还增加了现代科技元素，使得剧情更加贴近现实，同时也为观众提供了深刻的思考。', 'f', '2024-07-19 11:11:11.308587', 'admin', '2024-07-19 11:11:11.308587', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1822884492554145792, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '马龙被称为“六边形战士”是因为日本媒体《东京乒乓球新闻》使用了一种“二次元”六维雷达图来分析乒乓球选手的实力。这个雷达图从力量、速度、技巧、发球、防守、经验六个方面来评估选手的能力。马龙在这六个方面都表现出色，达到了满分的水平，因此他的雷达图呈现出一个完整的六边形，从而获得了“六边形战士”的称号。这个称号反映了马龙在乒乓球领域的全面和卓越能力。', 'f', '2024-08-12 14:35:05.238016', 'qinyuanpei', '2024-08-12 14:35:05.238016', 'qinyuanpei');
