INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1818163123903926272, 1772861261323833345, 'Z-XgdtSVGWJyVgtyoSXoo', 'RAG（Retrieval-Augmented Generation）是一种结合检索和生成的技术，其核心在于提高检索的召回率，即问题与文本块之间的相关性。无论大型模型是否发布，RAG都能正常落地，因为大型模型的推理能力影响的是最终的生成结果，而非检索的召回率。', 'f', '2024-07-30 13:54:03.233231', 'qinyuanpei', '2024-07-30 13:54:03.233231', 'qinyuanpei');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1818163558001807360, 1772861261323833345, 'Z-XgdtSVGWJyVgtyoSXoo', '解释一下什么叫做微服务', 't', '2024-07-30 13:55:46.73033', 'qinyuanpei', '2024-07-30 13:55:46.73033', 'qinyuanpei');
