INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1825471494722031616, 1798176607609950208, 'L7uwjlK2SUoBX20tyNznr', '许嵩，1986年5月14日出生于安徽省合肥市，毕业于安徽医科大学，是中国内地流行乐男歌手、词曲作者、编曲、音乐人，现任海蝶音乐公司（现为太合音乐集团）音乐总监。他自2006年起开始发表音乐作品，并以其笔名“Vae”在个人网站上传作品，引起了网友的关注。', 'f', '2024-08-19 17:54:54.619079', 'qinyuanpei', '2024-08-19 17:54:54.619079', 'qinyuanpei');
