INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1827920068781150208, 1798176607609950208, 'CatPm4sHTc_tJKCdKZITC', '姜维（202年－264年），字伯约，天水冀县（今甘肃甘谷东南）人，是三国时期蜀汉的著名军事家和将领。他原本是曹魏的将领，但在诸葛亮北伐时投降蜀汉，并受到诸葛亮的重用。诸葛亮去世后，姜维继续领导蜀汉军队北伐曹魏，多次取得战果。他的军事才能和忠诚于蜀汉的形象在历史上留下了深刻的印记。', 'f', '2024-08-26 12:04:40.16717', 'qinyuanpei', '2024-08-26 12:04:40.16717', 'qinyuanpei');
