INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846361377934020608, 1772861261323833345, 'oOaZamtRAKVCeBJnv88jG', '冬天来了-春天还会远吗', 't', '2024-10-16 09:23:50.891982', 'admin', '2024-10-16 09:23:50.891982', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846361600081137664, 1772861261323833345, 'oOaZamtRAKVCeBJnv88jG', '冬天来了，春天还会远吗？这句话表达了一种乐观的态度，即使在寒冷的冬天，也能看到春天的希望<sup>[6],[2],[3],[4],[7]</sup>。接到妈妈打来的电话时，时间已然接近中午时分，从床上爬起来的刹那间，就听见妈妈熟悉的声音<sup>[6],[7],[8],[9],[10]</sup>。妈妈问我年底公司有没有什么变动，顿时千万种思绪涌上心头，不知道该对电话彼端的妈妈说些什么<sup>[6],[7],[8],[9],[10]</sup>。我突然想到二十四岁时的我，从第一家公司裸辞时的情景，可如今，即使身处没有暖气的出租屋里，早晨带着体温的被子早已凉透，我依然对自己说，冬天来了，春天还会远吗？<sup>[6],[2],[3],[4],[7]</sup>

