INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1848637717894795264, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '长安是中国古代的一个著名城市，现在被称为西安。西安位于中国陕西省的中部，是陕西省的省会。西安有着悠久的历史，曾经是多个朝代的首都，包括西周、秦朝、汉朝和唐朝等。西安是中国历史文化名城之一，拥有丰富的历史遗迹，如兵马俑、大雁塔和古城墙等。', 'f', '2024-10-22 16:09:12.631374', 'admin', '2024-10-22 16:09:12.631374', 'admin');
