INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1848637943489630208, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '“天天向上”通常与“好好学习”连用，形成“好好学习，天天向上”的口号。这句话的含义是指认真地学习，每天都要注意提升自己的精神境界、道德水平和业务技能。这句话是毛泽东主席得悉苏州市金阊小学8岁小学生陈永康被特务打伤的事迹之后，亲笔题写的，并制作锦旗赠送给陈永康小朋友的。同时向全国的青少年发出了“好好学习，天天向上”的号召。', 'f', '2024-10-22 16:10:06.417283', 'admin', '2024-10-22 16:10:06.417283', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1848638315163684864, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '"人生自古谁无死" 是一句出自宋代文学家文天祥的《过零丁洋》的诗句。这句诗的意思是，自古以来，每个人都会面临死亡，这是人生的必然规律。这句诗表达了作者对人生无常和生死的深刻感悟，强调了生命的短暂和珍贵。', 'f', '2024-10-22 16:11:35.03135', 'admin', '2024-10-22 16:11:35.03135', 'admin');
