INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1848638631166742528, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '朱祁镇是明朝的第六位皇帝，他在位期间经历了多次重大事件，包括土木堡之变和夺门之变。他的统治时期充满了争议，既有政治上的失误，也有对国家稳定和发展的影响。要全面评价朱祁镇，建议查阅详细的历史资料和学术研究，以获取更深入的了解和多角度的评价。', 'f', '2024-10-22 16:12:50.371964', 'admin', '2024-10-22 16:12:50.371964', 'admin');
