INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846374269509046272, 1798176607609950208, 'X6sl70RinbTWkoBjqROh8', '朝韩冲突近期再度升级，主要原因是朝鲜指责韩国派遣无人机进入其领空并散发宣传单，进行“危险的挑衅”。作为回应，朝鲜炸毁了连接朝韩的部分公路路段，韩国军方对此进行了反制。中国呼吁避免半岛紧张局势进一步升级。朝韩冲突的历史背景复杂，双方都宣称对整个朝鲜半岛拥有主权。', 'f', '2024-10-16 10:15:04.469593', 'admin', '2024-10-16 10:15:04.469593', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1830886306276839424, 1798176607609950208, 'CatPm4sHTc_tJKCdKZITC', '姜维（202年～264年3月3日），字伯约，天水郡冀县（今甘肃省天水市甘谷县）人，是三国时期蜀汉名将。他在历史上以攻代守，为蜀汉的振兴奔走，继承了先师诸葛亮的教诲，组织多次北伐，虽败犹荣，是蜀汉中后期的顶梁之柱。', 'f', '2024-09-03 16:31:26.296287', 'admin', '2024-09-03 16:31:26.296287', 'admin');
