INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846456016443674624, 1772861261323833345, 'LaFTZiHg9CpoVm-BaQ07X', '西施被描述为天下最美的女子，她的美貌让阿青感到惊奇、羡慕和崇敬<sup>[1]</sup>。范蠡也曾仔细地描述过西施的美貌，说她白雪一般的手伸到湘江里，柔和得好像要溶在水里一样<sup>[2]</sup>。

