INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846386301927034880, 1798176607609950208, 'X6sl70RinbTWkoBjqROh8', '“三八线”是朝鲜半岛上北纬38度附近的一条军事分界线。它是在1945年盟军托管朝鲜时期，苏联和美国在从日本手中接收朝鲜半岛过程中，按土地面积大致相等原则划定的一条受降分界线。这条线后来成为朝鲜战争期间的停火线，并成为朝鲜民主主义人民共和国和大韩民国之间的非军事区。三八线全长约248公里，宽度大约4公里，双方一度都有重兵把守，并互相播放广播。近年来局势有所缓和，基本没有冲突。此外，“三八线”也是一部由中国导演梦继执导的年代战争剧的名称，讲述了1950年朝鲜战争期间志愿军的故事。', 'f', '2024-10-16 11:02:53.235063', 'admin', '2024-10-16 11:02:53.235063', 'admin');
