INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1847107560365232128, 1798176607609950208, 'gMjT9UhvOGrghN8f5ibgs', '《唐多令·芦叶满汀洲》是南宋词人刘过创作的一首词，全文如下：

芦叶满汀洲，寒沙带浅流。二十年重过南楼。柳下系船犹未稳，能几日，又中秋。
黄鹤断矶头，故人今在否？旧江山浑是新愁。欲买桂花同载酒，终不似，少年游。

这首词的背景是刘过在安远楼与朋友名士聚会，二十年后重游此地，感慨今昔，因此写了这首词。词中抒发了对时光流逝、物是人非的世道沧桑的强烈感受，以及怀才不遇的思想感情。

这句话“欲买桂花同载酒，终不似，少年游”表达了作者对逝去青春的怀念和对现实境遇的无奈，体现了时光流逝、物是人非的感慨。', 'f', '2024-10-18 10:48:54.647032', 'admin', '2024-10-18 10:48:54.647032', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1847108350702129152, 1798176607609950208, 'gMjT9UhvOGrghN8f5ibgs', '你知道姜夔最出名的一首词是什么嘛', 't', '2024-10-18 10:52:03.077984', 'admin', '2024-10-18 10:52:03.077984', 'admin');
