INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846389003339829248, 1798176607609950208, 'X6sl70RinbTWkoBjqROh8', '坂本龙马是日本幕末时期的著名人物，出生于1836年，是日本明治维新时代的维新志士，倒幕维新运动活动家，思想家。他两度脱藩成为维新志士，是促成萨摩及长州二藩成立军事同盟的重要推手之一。他提出的船中八策对日本的现代化进程产生了深远影响。坂本龙马在1867年被暗杀，但他的思想和行动对日本的历史进程产生了重大影响，至今仍被视为日本历史上的一位传奇人物。', 'f', '2024-10-16 11:13:37.302841', 'admin', '2024-10-16 11:13:37.302841', 'admin');
