INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846015774754476032, 1798176607609950208, 'IdLhZ6LbUNbZeYn6Jj-Ed', '六国破灭，非秦之强，实六国之弱也。六国之君，或贪图小利，或内政不修，或外交失策，或军事不力，皆为秦所乘。秦国则励精图治，内修政理，外结盟友，兵强马壮，终成一统之势。故曰：六国之亡，非天命也，实人事之不臧也。', 'f', '2024-10-15 10:30:32.673783', 'admin', '2024-10-15 10:30:32.673783', 'admin');
