INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1856174226898292736, 1798176607609950208, 'fNs7Fnj1MR9Mwg9_BSw2y', '论文 "1504.05035v1" 的标题是 "F-SVM: Combination of Feature Transformation and SVM Learning via Convex Relaxation"。作者包括 Xiaohe Wu, Wangmeng Zuo, Yuanyuan Zhu, 和 Liang Lin。论文提出了一种新的凸半径-边界支持向量机模型（F-SVM），用于联合学习特征变换和支持向量机分类器。通过实验，F-SVM 在 UCI 机器学习数据集和 LFW 人脸数据集上表现优于标准 SVM 和其他基于半径-边界的 SVM 模型，如 RMM, R-SVM+ 和 R-SVM+{\\mu}。', 'f', '2024-11-12 11:16:36.399403', 'admin', '2024-11-12 11:16:36.399403', 'admin');
