INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1831199891054006272, 1798176607609950208, 'adltLYOXnYIrexIV-1yCW', '- 历史上的今天发生的事件包括：
