INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846034583473229824, 1798176607609950208, '1fk0I8jbIRFW2-tBkBjG3', '- 
```sql
WITH RankedStadium AS (
    SELECT
        id,
        people,
        ROW_NUMBER() OVER (ORDER BY id) - ROW_NUMBER() OVER (PARTITION BY people >= 100 ORDER BY id) AS grp
    FROM
        Stadium
    WHERE
        people >= 100
)
SELECT
    id,
    people
FROM
    RankedStadium
WHERE
    grp IN (
        SELECT
            grp
        FROM
            RankedStadium
        GROUP BY
            grp
        HAVING
            COUNT(*) >= 3
    )
ORDER BY
    id;
```', 'f', '2024-10-15 11:45:17.021536', 'admin', '2024-10-15 11:45:17.021536', 'admin');
