INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846035467804479488, 1798176607609950208, '1fk0I8jbIRFW2-tBkBjG3', '对于表 Stadium，visit_date 是该表中具有唯一值的列。每日人流量信息被记录在这三列信息中：序号 (id)、日期 (visit_date)、 人流量 (people)每天只有一行记录，日期随着 id 的增加而增加。请编写解决方案找出每行的人数大于或等于 100 且 id 连续的三行或更多行记录。返回按 visit_date 升序排列 的结果表。

返回按 visit_date 升序排列 的结果表。', 't', '2024-10-15 11:48:47.861968', 'admin', '2024-10-15 11:48:47.861968', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846035614550593536, 1798176607609950208, '1fk0I8jbIRFW2-tBkBjG3', '- 
```sql
WITH RankedStadium AS (
    SELECT
        id,
        visit_date,
        people,
        id - ROW_NUMBER() OVER (ORDER BY id) AS grp
    FROM
        Stadium
    WHERE
        people >= 100
)
SELECT
    id,
    visit_date,
    people
FROM
    RankedStadium
WHERE
    grp IN (
        SELECT
            grp
        FROM
            RankedStadium
        GROUP BY
            grp
        HAVING
            COUNT(*) >= 3
    )
ORDER BY
    visit_date;
```', 'f', '2024-10-15 11:49:22.849624', 'admin', '2024-10-15 11:49:22.849624', 'admin');
