INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1849326673082847232, 1798176607609950208, 'CatPm4sHTc_tJKCdKZITC', '许昕是一位中国男子乒乓球运动员，出生于1990年1月8日，江苏徐州人。他是国际级运动健将，擅长左手正手全台攻击和反手拨球。许昕在乒乓球领域取得了显著成就，包括东京奥运会乒乓球混双亚军、2012年国际乒联总决赛男单冠军、2013年乒乓球世界杯男单冠军等。此外，他还创立了自己的乒乓球品牌Xuperman，并在社交媒体上活跃。', 'f', '2024-10-24 13:46:52.348634', 'admin', '2024-10-24 13:46:52.348634', 'admin');
