INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846846313329725440, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '这首诗描绘了春日小雨中的溪流景象，鹅鸭在水中嬉戏，不知春天已尽，争相追逐桃花。诗句如下：

阴阴溪曲绿交加，
小雨翻萍上浅沙。
鹅鸭不知春去尽，
争随流水趁桃花。', 'f', '2024-10-17 17:30:48.489653', 'admin', '2024-10-17 17:30:48.489653', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846846688770265088, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '《追风筝的人》主要讲述了12岁的阿富汗富家少爷阿米尔与仆人哈桑之间的深厚友谊。然而，在一场风筝比赛后，阿米尔因自己的懦弱感到自责，导致哈桑被逼走。随后，阿米尔与父亲逃往美国。多年后，阿米尔意识到往事无法被埋葬，始终在心中挥之不去。这本书深刻探讨了友谊、背叛、救赎和自我发现的主题。', 'f', '2024-10-17 17:32:18.011886', 'admin', '2024-10-17 17:32:18.011886', 'admin');
