INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846850778749341696, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '蜘蛛侠被戏称为钢铁侠的“亲儿子”，主要是因为在漫威电影宇宙中，托尼·斯塔克（钢铁侠）对彼得·帕克（蜘蛛侠）有着类似父亲般的关怀和指导。托尼在电影中多次帮助和指导彼得，甚至在某些情况下像父亲一样保护他，这种深厚的情感联系使得粉丝们将彼得视为托尼的“亲儿子”。', 'f', '2024-10-17 17:48:33.139327', 'admin', '2024-10-17 17:48:33.139327', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846851897173086208, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '漫改电影《浪客剑心》系列在观众中获得了较高的评价，被认为是精品中的精品。观众普遍认为其在打斗场面和角色内心戏的表现上都非常出色，尤其是在感情线的处理上，如巴与剑心的感情线，被认为是亮点。此外，电影在选角和造型上也几乎无可挑剔，被认为是对原作的忠实再现。总体来说，《浪客剑心》系列在漫改电影中表现出色，深受观众喜爱。', 'f', '2024-10-17 17:52:59.791796', 'admin', '2024-10-17 17:52:59.791796', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1846852239549927424, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '《踏浪》这首歌通过描绘自然景观和轻快的旋律，表达了对大自然的热爱和对生活的向往。歌词中的“小小的一片云”和“山上的山花儿”等元素，传达了一种清新、自然的生活态度，反映了人们对简单、美好生活的渴望。这首歌的轻快旋律和简单歌词，使其成为一首深受人们喜爱的校园歌曲。', 'f', '2024-10-17 17:54:21.421423', 'admin', '2024-10-17 17:54:21.421423', 'admin');
