INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1848968061781151744, 1798176607609950208, 'sbzdnvb0WjhfNXv-ydXtn', '在《大明风华》中，张艺兴饰演的角色是朱祁镇。朱祁镇是明朝的皇帝，经历了许多坎坷，包括被俘虏等情节。张艺兴通过这部剧展现了他出色的演技，成功塑造了这个角色。', 'f', '2024-10-23 14:01:52.751209', 'admin', '2024-10-23 14:01:52.751209', 'admin');
