INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1866054377731657728, 1798176607609950208, 'wrlYyFznaimTA-t61lEE9', '《妖猫传》是一部2017年上映的中国电影，故事发生在盛唐时期的长安城。电影讲述了白乐天（黄轩 饰）和日本僧人空海（染谷将太 饰）携手调查一系列离奇死亡事件的故事。这些事件与一只神出鬼没的妖猫有关，而妖猫的出现又与三十年前杨贵妃（张榕容 饰）的死亡有着千丝万缕的关联。通过追寻阿部仲麻吕（阿部宽 饰）留下的日记，两人见证了大唐曾经的荣光，并揭开了当年隐瞒至今的阴谋。', 'f', '2024-12-09 17:36:47.922398', 'admin', '2024-12-09 17:36:47.922398', 'admin');
