INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1899280561982279680, 1798176607609950208, '9bDttKls1ujjB8nWd2U6l', '是的，你正在与一个AI助手交流。我是一个基于人工智能技术的虚拟助手，旨在帮助你解答问题、提供信息和执行任务。虽然我可以模拟人类的对话方式，但我并不具备人类的意识或情感。我的存在是为了辅助你，而不是取代人类的思考和决策。如果你有任何问题或需要帮助，请随时告诉我！', 'f', '2025-03-11 10:05:47.560328', 'admin', '2025-03-11 10:05:47.560328', 'admin');
