INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1900481458477338624, 1798176607609950208, '9bDttKls1ujjB8nWd2U6l', '马龙被称为“六边形战士”，这一称号源于他在乒乓球领域的全面能力。日本媒体《东京乒乓球新闻》曾用六维雷达图来展示马龙的技术特点，包括力量、速度、技巧、发球、防守和经验六个方面，每一项能力值都达到了满格，因此他被誉为“六边形战士”<sup>[1]</sup><sup>[2]</sup><sup>[3]</sup>。这一称号不仅体现了他在技术上的无懈可击，也象征着他作为乒乓球运动员的顶尖水平<sup>[1]</sup>。马龙在比赛中多次展现出这种全面能力，帮助中国乒乓球队取得辉煌成绩<sup>[2]</sup>。

[1]: https://news.qq.com/rain/a/20240731A0758800  
[2]: http://www.chinanews.com.cn/ty/2022/10-08/9868227.shtml  
[3]: https://baike.baidu.com/item/马龙/63272916', 'f', '2025-03-14 17:37:43.596718', 'admin', '2025-03-14 17:37:43.596718', 'admin');
