INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1873929349590290432, 1798176607609950208, 'A_2dY6gtWL9SQB9CgcCBq', '路易吉事件是指2013年12月，美国路易吉公司生产的冷冻意大利面制品被检出含有沙门氏菌，导致多人感染的事件。事件发生后，路易吉公司召回了相关产品。这一事件提醒我们食品安全的重要性，企业应加强生产过程中的质量控制，确保消费者的健康安全。', 'f', '2024-12-31 11:09:07.523444', 'admin', '2024-12-31 11:09:07.523444', 'admin');
