INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1894305260349034496, 1772861261323833345, 'rX8xjeLROX-OhCnveg8sb', 'AI，即人工智能（Artificial Intelligence），是指由人制造出来的智能系统，这些系统能够模拟、延伸和扩展人类智能到机器上。人工智能技术可以执行多种任务，包括但不限于语言理解、视觉识别、决策支持和预测分析。它们可以基于数据和算法自主学习和改进，以提高性能和适应性。<sup>[1]</sup><sup>[2]</sup>

