INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1864122081533366272, 1798176607609950208, '5cwJ_nxmqUBLXW_u7BuJs', '马龙被称为“六边形战士”是因为日本媒体《东京乒乓球新闻》使用了一个“二次元”六维雷达图，从力量、速度、技巧、发球、防守、经验六个方面分析乒乓球选手的实力。马龙在这六个方面的能力值都是满分，他的能力撑爆了“六边形”，因此被日本媒体称为“六边形战士”。这个称号反映了马龙在乒乓球领域的全面实力和卓越表现。', 'f', '2024-12-04 09:38:32.607679', 'admin', '2024-12-04 09:38:32.607679', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1864122635441541120, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '马龙被称为“六边形战士”是因为日本媒体《东京乒乓球新闻》使用了一个“二次元”六维雷达图，从力量、速度、技巧、发球、防守、经验六个方面分析乒乓球选手的实力。马龙在这六个方面的能力值都是满分，意味着他在乒乓球领域没有明显的弱点，各项技术都非常全面和均衡，因此获得了“六边形战士”的称号。', 'f', '2024-12-04 09:40:44.670296', 'admin', '2024-12-04 09:40:44.670296', 'admin');
