INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1866056788420464640, 1798176607609950208, 'wrlYyFznaimTA-t61lEE9', '马伯庸，原名马力，男，满族，出生于1980年，内蒙古自治区赤峰市人。他是一位中国当代作家、编剧，中国作家协会会员，文学创作一级。马伯庸毕业于新西兰怀卡多大学经管系，2005年开始发表作品，2018年加入中国作家协会。他的作品涵盖了科幻、奇幻、历史、灵异、推理、动漫等多个领域，代表作有长篇小说《古董局中局》、《风起陇西》、《三国机密》，中篇小说《末日焚书》、《街亭杀人事件》，散文《风雨》、《破案：孔雀东南飞》等。马伯庸的作品以其天马行空的想象力和严谨的考据癖著称，被誉为“文字鬼才”和“马亲王”。他还是南京大学文学院兼职教授，南京大学“中国文学与东亚文明协同创新中心”学术顾问。', 'f', '2024-12-09 17:46:22.675092', 'admin', '2024-12-09 17:46:22.675092', 'admin');
