INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1873930016157470720, 1798176607609950208, 'xAtsPbT_XTMKDdCISZwRH', '马龙被称为“六边形战士”是因为他在乒乓球技术上的全面性。这个称号源自日本媒体的评价体系，用六边形雷达图展示选手在力量、速度、技术、发球、防守和心态六个方面的能力。马龙在这六个方面都表现出色，几乎达到了满分，因此被称为“六边形战士”，体现了他在技术上的全面性和作为顶级选手的统治力。', 'f', '2024-12-31 11:11:46.445592', 'admin', '2024-12-31 11:11:46.445592', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1873930041092608000, 1798176607609950208, 'xAtsPbT_XTMKDdCISZwRH', '许昕为什么被成为大蟒', 't', '2024-12-31 11:11:52.390569', 'admin', '2024-12-31 11:11:52.390569', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1873930063985119232, 1798176607609950208, 'xAtsPbT_XTMKDdCISZwRH', '许昕被称为“大蟒”是因为他的乒乓球技术特点与蟒蛇相似。他的“蟒蛇式”打法以灵活多变、旋转强烈和线路诡异著称，使得对手难以捉摸和应对。这种打法如同蟒蛇般缠绕对手，因此得名“大蟒”。此外，许昕在比赛中的顽强拼搏精神和出色的防守反击能力也进一步强化了这一绰号。', 'f', '2024-12-31 11:11:57.848008', 'admin', '2024-12-31 11:11:57.848008', 'admin');
