INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1866033815575728128, 1798176607609950208, '-yrrDM_QACkiJ0UzucK7Y', '许嵩（Vae），1986年5月14日生于安徽省合肥市，是中国内地流行乐男歌手、词曲创作人、音乐制作人。他现任海蝶音乐公司（现为太合音乐集团）音乐总监，毕业于安徽医科大学。许嵩以其独特的音乐风格和才华横溢的创作能力在中国音乐界享有盛誉。他的音乐作品深受广大听众喜爱，代表作包括《自定义》、《呼吸之野》等。', 'f', '2024-12-09 16:15:05.522213', 'admin', '2024-12-09 16:15:05.522213', 'admin');
