INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1864846552128950272, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '- 以下是生成的 Vue 的 HelloWorld 组件代码：

