INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1861647465170735104, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '电视剧《仁医》中的穿越是通过一次意外事件实现的。主角南方仁医生在一次手术后追赶一名神秘男子时，从台阶摔下昏迷，醒来后发现自己已经穿越到了幕末的江户时代。在这个时代，他遇到了许多历史人物，并试图将现代医疗技术引入江户，同时也在努力改变历史中众人的命运。', 'f', '2024-11-27 13:45:18.091481', 'admin', '2024-11-27 13:45:18.091481', 'admin');
