INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1901485038176964608, 1798176607609950208, '-yrrDM_QACkiJ0UzucK7Y', '根据分析，新浪微博用户 @许嵩 是一位知名的音乐人、歌手和词曲创作者。他的微博粉丝数量高达1616.1万，关注数量为124。许嵩的性格外向且情绪稳定，表现出高度的创造力和开放性。他非常重视与粉丝的互动，频繁在微博上表达对粉丝的感激之情。许嵩的主要兴趣包括音乐创作、文学与诗歌、旅行与探索以及影视与艺术。他通过微博分享自己的音乐作品，展示对生活的热爱和对未来的期待。', 'f', '2025-03-17 12:05:35.64235', 'admin', '2025-03-17 12:05:35.64235', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1901517830768168960, 1798176607609950208, '-yrrDM_QACkiJ0UzucK7Y', '为什么是上厕所、下厨房', 't', '2025-03-17 14:15:54.004565', 'admin', '2025-03-17 14:15:54.004565', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1901518135773761536, 1798176607609950208, '-yrrDM_QACkiJ0UzucK7Y', '在汉语中，“上厕所”和“下厨房”这两个表达的使用可能与古代建筑布局和文化习惯有关。在古代，厕所通常建在房屋的高处或远离居住区的地方，因此用“上”来表示去厕所。而厨房则通常建在房屋的低处或靠近居住区的地方，因此用“下”来表示去厨房。这种表达方式反映了古代人们对生活空间的布局和功能的理解。', 'f', '2025-03-17 14:17:06.724578', 'admin', '2025-03-17 14:17:06.724578', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1901537901775294464, 1798176607609950208, 'oZOzLo4_bZt5q4vx8SrAj', '这是一张可爱的小猫咪图片，你可以点击以下链接查看：[小猫咪图片](https://cdn2.thecatapi.com/images/2f5.jpg)', 'f', '2025-03-17 15:35:39.306439', 'admin', '2025-03-17 15:35:39.306439', 'admin');
