INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1900377739404382208, 1798176607609950208, 'uBVoZXNhCXXbFcqyfVqRK', '福建的土楼和土家族没有直接关系。福建土楼是福建省西南部客家人的传统民居建筑，而土家族是分布在湖南、湖北、重庆、贵州等地的少数民族，两者在地理分布、文化和民族背景上都没有直接联系。', 'f', '2025-03-14 10:45:35.042517', 'admin', '2025-03-14 10:45:35.042517', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1900378528361353216, 1798176607609950208, 'uBVoZXNhCXXbFcqyfVqRK', '这两个不是都有土吗？怎么会没有关系，到底有没有关系', 't', '2025-03-14 10:48:43.144656', 'admin', '2025-03-14 10:48:43.144656', 'admin');
