INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1873960006970380288, 1798176607609950208, 'A_2dY6gtWL9SQB9CgcCBq', '马龙被称为“六边形战士”是因为他在乒乓球领域的全面表现。这一称号源自日本媒体对乒乓球选手的综合能力评估，通常用六边形雷达图来表示选手在力量、速度、技术、发球、接发球和战术六个方面的能力。马龙在这六个方面都表现出色，几乎没有短板，因此被称为“六边形战士”。他的全面能力使他在国际比赛中屡获佳绩，成为中国乒乓球队的核心人物之一。', 'f', '2024-12-31 13:10:56.812165', 'admin', '2024-12-31 13:10:56.812165', 'admin');
