INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1900379064858972160, 1798176607609950208, 'uBVoZXNhCXXbFcqyfVqRK', '土楼和土家族虽然名称中都包含“土”字，但它们并没有直接的关系。土楼是一种建筑形式，主要分布在福建省，而土家族是中国的一个少数民族，主要分布在湖南、湖北、贵州等地。它们的“土”字来源不同，土楼的“土”指的是建筑材料，而土家族的“土”则是民族名称的一部分。', 'f', '2025-03-14 10:50:51.054957', 'admin', '2025-03-14 10:50:51.054957', 'admin');
