INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1863852393050017792, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '马龙被称为“六边形战士”是因为他在乒乓球领域的各项能力都非常全面，几乎没有任何短板。这个称号源于日本媒体《东京乒乓球新闻》用“二次元”六维雷达图来演示马龙各项能力，每一项能力值都是拉满的，形成了一个完整的六边形。这意味着马龙在力量、速度、技巧、发球、防守、经验等方面都达到了顶尖水平，因此被形象地称为“六边形战士”。', 'f', '2024-12-03 15:46:53.863188', 'qinyuanpei', '2024-12-03 15:46:53.863188', 'qinyuanpei');
