INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1862371179919183872, 1798176607609950208, '1fk0I8jbIRFW2-tBkBjG3', '查询数据库，帮我查询国家为美国的顾客信息，以表格的形式返回顾客的姓名、公司、地址、城市、邮件、电话等信息', 't', '2024-11-29 13:41:05.133205', 'qinyuanpei', '2024-11-29 13:41:05.133205', 'qinyuanpei');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1862372549556572160, 1798176607609950208, '1fk0I8jbIRFW2-tBkBjG3', '对于表 Stadium，visit_date 是该表中具有唯一值的列。每日人流量信息被记录在这三列信息中：序号 (id)、日期 (visit_date)、 人流量 (people)每天只有一行记录，日期随着 id 的增加而增加。请编写解决方案找出每行的人数大于或等于 100 且 id 连续的三行或更多行记录。返回按 visit_date 升序排列 的结果表。

返回按 visit_date 升序排列 的结果表。', 't', '2024-11-29 13:46:31.669102', 'qinyuanpei', '2024-11-29 13:46:31.669102', 'qinyuanpei');
