INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1863853999787216896, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '西安市未来一周的天气预报如下：

