INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1901940537632624640, 1798176607609950208, '9bDttKls1ujjB8nWd2U6l', '堺雅人是一位演技精湛的演员，以其多变的表演风格和深入的角色刻画而闻名。他在《半泽直树》、《Legal High》等作品中的表现得到了观众和影评人的高度评价，尤其是在情感表达和角色塑造方面展现了卓越的才华。堺雅人的演技不仅具有广泛的适应性，还能在不同类型的角色中保持高度的真实感和深度，使他成为日本影视界的重要人物。', 'f', '2025-03-18 18:15:35.175671', 'admin', '2025-03-18 18:15:35.175671', 'admin');
