INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1897906538023096320, 1798176607609950208, 'QGoVGahEbaSUHCtAcOIOn', '李白是谁？', 't', '2025-03-07 15:05:54.720595', 'admin', '2025-03-07 15:05:54.720595', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1897906814952017920, 1798176607609950208, 'QGoVGahEbaSUHCtAcOIOn', '李白是中国唐朝著名的浪漫主义诗人，被誉为“诗仙”。他出生于公元701年2月28日，祖籍陇西成纪（今甘肃省秦安县），出生于绵州昌隆县（今四川省江油市青莲镇）。李白的诗歌雄浑瑰奇，气象万千，尤其以绝句和乐府诗最为著名，对后世影响深远<sup>[1]</sup><sup>[2]</sup><sup>[3]</sup>。他的诗才被贺知章等人推崇，唐玄宗曾召他入仕翰林<sup>[4]</sup>。李白一生游历四方，留下了大量脍炙人口的诗篇，如《临终歌》等<sup>[5]</sup>。

[1]: https://www.zhihu.com/question/597737587  
[2]: https://www.xiaoxiaoshenghuo.com/article/0820/2207171.html  
[3]: https://www.lishirenwu.com/tangchaogushi/42993.html  
[4]: http://wenhui.whb.cn/zhuzhanapp/tj/20191202/306306.html?tm=104430000  
[5]: https://www.lishirenwu.com/lishirenwugushi/53867.html', 'f', '2025-03-07 15:07:00.745121', 'admin', '2025-03-07 15:07:00.745121', 'admin');
