INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1899750082522255360, 1798176607609950208, '9bDttKls1ujjB8nWd2U6l', '“饺子的王将”是一家发源于日本京都市的连锁餐厅，主要销售大阪风味的日式煎饺。它在日本全国各地拥有500多家分店<sup>[2]</sup>。尽管名称与另一家著名饺子店“大阪王将”相似，但“饺子的王将”起源于京都，因此有时被称为“京都王将”以作区分<sup>[2]</sup>。此外，该公司的老板大东孝之曾涉及一起不正当交易案件，涉案金额高达260亿日元<sup>[3]</sup>。

[1]: https://zhuanlan.zhihu.com/p/579235607  
[2]: https://zh.m.wikipedia.org/zh-hans/大阪王將  
[3]: https://www.zhihu.com/question/610749816', 'f', '2025-03-12 17:11:29.979197', 'admin', '2025-03-12 17:11:29.979197', 'admin');
