INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1863449905071263744, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '- 这篇论文介绍了一种新的机器学习算法，该算法在图像识别任务中表现出色。作者提出了一种基于深度学习的模型，该模型结合了卷积神经网络（CNN）和递归神经网络（RNN）的优点。实验结果表明，该算法在多个基准数据集上达到了最先进的性能。', 'f', '2024-12-02 13:07:33.251471', 'admin', '2024-12-02 13:07:33.251471', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1863468948704595968, 1798176607609950208, '0iQvv4vg_ptsB9f7ol-h2', '总结一下以下论文的主要内容：https://arxiv.org/pdf/2411.01236', 't', '2024-12-02 14:23:13.607607', 'admin', '2024-12-02 14:23:13.607607', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1930905247736270848, 1930872164936978432, '0hD54kfMEkxAV9dNbMWJj', '帮我生成一个提交数据的表单，包括事故发生位置、事故类型、事故发生时间、事故详情、事故上报人等信息，其中事故发生位置是一组经纬度，需要从地图上获取，地图请使用开源地图，样式请使用 Tailwind CSS ', 't', '2025-06-06 16:31:00.201719', 'admin', '2025-06-06 16:31:00.201719', 'admin');
