INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1866737793926041600, 1798176607609950208, '18vRhR3nXSCcgpE94b_Of', '过去一周内，美股整体呈现上涨趋势，标普500指数上涨了1.4%，创下历史新高，其中284只股票收涨。科技股和主要指数如道琼斯工业指数等均显示出强劲的上涨势头。尽管存在一些宏观经济和政治因素的不确定性，但市场整体表现积极。', 'f', '2024-12-11 14:52:27.039819', 'admin', '2024-12-11 14:52:27.039819', 'admin');
