INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1866738889625047040, 1798176607609950208, '18vRhR3nXSCcgpE94b_Of', '生成的表单页面已经包含了所有所需的信息字段，并且事故发生位置的经纬度可以通过地图组件来获取。用户可以在地图上点击选择事故发生的位置，经纬度会自动填充到表单中。表单还包括事故类型、事故发生时间、事故详情和事故上报人等字段。用户填写完所有信息后，可以点击提交按钮，表单数据将以JSON格式输出到控制台。', 'f', '2024-12-11 14:56:48.27551', 'admin', '2024-12-11 14:56:48.27551', 'admin');
