INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1902234815210590208, 1798176607609950208, 'QocaZjuFlSWf9tnEkWxfF', '根据分析，@云来雁去 是一位30岁左右的男性，居住在西安，从事技术相关工作。他的性格平和、幽默，情绪稳定，对AI技术、文学、哲学等有浓厚兴趣。他喜欢分享生活中的点滴，尤其是自然风景和技术进展。他的微博内容展现出较高的开放性和尽责性，情绪波动较小，整体呈现出一种积极向上的生活态度。', 'f', '2025-03-19 13:44:56.417293', 'admin', '2025-03-19 13:44:56.417293', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1902242100389482496, 1798176607609950208, 'QocaZjuFlSWf9tnEkWxfF', '这篇论文的主要内容是研究气候变化对全球农业生产力的影响。通过结合历史气候数据和未来气候预测，研究发现气候变化可能导致农业产量显著下降，特别是在粮食不安全的地区。论文还探讨了可能的适应策略，以减轻气候变化对农业的负面影响。', 'f', '2025-03-19 14:13:53.339241', 'admin', '2025-03-19 14:13:53.339241', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1902247851543629824, 1798176607609950208, 'gMjT9UhvOGrghN8f5ibgs', '类似辛弃疾、霍去病这样的名字包括：
