INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1902621818074828800, 1798176607609950208, 'EunP8rXGqKhFJtSVJdIby', 'GitHub 仓库 "mannaandpoem/OpenManus" 是一个开源框架，旨在构建通用的 AI 代理。项目由 MetaGPT 团队开发，支持多语言和多种安装方式，提供了快速启动和配置指南。项目活跃度高，欢迎社区贡献，采用 MIT 许可证，并提供了详细的文档和社区交流渠道。', 'f', '2025-03-20 15:22:45.08928', 'admin', '2025-03-20 15:22:45.08928', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1902625621394198528, 1798176607609950208, 'EunP8rXGqKhFJtSVJdIby', 'OpenRouter 是一个大模型 API 路由器，旨在将各种 AI 模型和服务集成到一个统一的接口中。它允许用户通过单一的 API 访问和使用多种 AI 模型，包括 GPT-4、Claude 和开源模型等<sup>[1]</sup><sup>[5]</sup>。OpenRouter 提供了一个市场平台，用户可以比较不同模型的性能和价格，选择最适合自己的服务<sup>[3]</sup><sup>[4]</sup>。此外，它还支持免费使用部分开源模型，避免了复杂的部署问题<sup>[5]</sup><sup>[6]</sup>。通过 OpenRouter，开发者和用户可以轻松访问丰富的 AI 应用资源，涵盖聊天、角色扮演、编程等多个领域<sup>[3]</sup><sup>[4]</sup>。

[1]: https://www.aipintai.com/OpenRouter.html  
[2]: https://ai-bot.cn/openrouter/  
[3]: https://www.dongaigc.com/p/tools/openrouter/related  
[4]: https://www.dongaigc.com/p/tools/openrouter  
[5]: https://langlangy.com/archives/wu-xu-gpu-fu-wu-qi-jie-zhu-openrouter-ling-cheng-ben-da-jian-zi-ji-de-da-mo-xing-zhu-shou  
[6]: https://blog.csdn.net/hellocode_/article/details/145045094', 'f', '2025-03-20 15:37:51.872108', 'admin', '2025-03-20 15:37:51.872108', 'admin');
