INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1910628630216708096, 1798176607609950208, 'LPphHrmPkKlJ-G-d60bRU', '介绍一下今川义元，并就他与织田信长之间的战争过程进行说明', 't', '2025-04-11 17:38:57.864078', 'admin', '2025-04-11 17:38:57.864078', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1910629331797938176, 1798176607609950208, 'LPphHrmPkKlJ-G-d60bRU', '今川义元是日本战国时代东海道的大名，今川氏第11代当主，通过政治联姻和军事扩张使今川氏达到全盛，被称为“东海道第一弓取”。他推行多项政策加强统治，但在1560年的桶狭间之战中被织田信长奇袭身亡，导致今川氏迅速衰落。

织田信长是战国时代最具影响力的武将之一，早年被称为“尾张的大傻瓜”，但通过桶狭间之战一举成名。他推行改革政策，推翻室町幕府，几乎统一日本中部地区，为后来的丰臣秀吉统一日本奠定基础。

二者之间的关键战争是1560年的桶狭间之战：今川义元率大军西进时，织田信长以少胜多，利用暴雨和地形优势发动奇袭，在今川军休息的桶狭间击杀今川义元。这场战役使织田信长崭露头角，同时标志着今川氏的衰落，是战国时代的重要转折点。', 'f', '2025-04-11 17:41:45.13427', 'admin', '2025-04-11 17:41:45.13427', 'admin');
