INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1912782397372502016, 1798176607609950208, '4nuygvmA6YFwObMzJwVqq', '日本战国时期主要大名势力范围分布图（简版）：

