INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1913147905896747008, 1798176607609950208, '5XnQL26g_9k-6Nd3-ObrP', '已完成事故报告表单的验证逻辑和提交处理功能的添加。生成的表单具有以下特性：

