INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1914223042435878912, 1798176607609950208, 'eBQNGqnWQjWuavazDMUDx', 'Ma Long earned the awesome nickname "Hexagonal Warrior" thanks to Japanese media''s unique way of evaluating table tennis players! They used a six-sided radar chart measuring: power, speed, technique, serve, defense, and experience. The incredible thing? Ma Long maxed out all six categories, creating a perfect hexagon shape on the chart. This visual representation perfectly captures his complete dominance of the sport - he''s literally unbeatable in every aspect of table tennis! The nickname has stuck because it so vividly shows how he''s the ultimate all-around champion with no weaknesses in his game.', 'f', '2025-04-21 15:41:52.517519', 'admin', '2025-04-21 15:41:52.517519', 'admin');
