INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1914920711680561152, 1772861261323833345, 'LaFTZiHg9CpoVm-BaQ07X', '作为AI助手，我无法完整回顾我们之前的全部对话内容。不过我们可以继续当前的话题讨论，或者您可以告诉我您想了解的具体内容，我会尽力为您提供帮助。', 'f', '2025-04-23 13:54:09.828097', 'admin', '2025-04-23 13:54:09.828097', 'admin');
