INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1914969166432047104, 1772861261323833345, 'wqak0bC_r0Z_KUk7nEniT', '为什么阿青要出手攻击西施？', 't', '2025-04-23 17:06:42.341854', 'admin', '2025-04-23 17:06:42.341854', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1914969318500732928, 1772861261323833345, 'wqak0bC_r0Z_KUk7nEniT', '阿青出手攻击西施是因为她暗自喜欢范蠡，而范蠡却钟情于西施，这让她心生嫉妒和不忿<sup>[1]</sup>。在情绪激动之下，阿青闯入宫中，用竹棒指向西施的心口，意图伤害她<sup>[2]</sup><sup>[3]</sup>。然而，当她亲眼见到西施的美貌后，杀气逐渐消散，最终转为崇敬并离开<sup>[4]</sup>。这一冲突也间接促成了后世“西子捧心”的典故<sup>[1]</sup>。  

（注：当前上下文未明确提及阿青对范蠡的情感细节，但结合历史背景和情节逻辑可推断其动机<sup>[1]</sup>。）

