INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1927551914967437312, 1798176607609950208, 'e-StW30mk8v4CbXy3XhKV', '为您推荐以下三道适合两人晚餐的家常菜，简单易做又美味：

