INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1921867450757025792, 1798176607609950208, 'DIedEt6aCK1srTEq25ctV', '现在是17:58，距离下班还有2分钟，马上就要下班啦！', 'f', '2025-05-12 17:58:01.488236', 'admin', '2025-05-12 17:59:06.197885', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1921867876919283712, 1798176607609950208, 'DIedEt6aCK1srTEq25ctV', '现在是2025年5月12日18:00，下班时间到啦！🎉 我为您准备了一些放松身心的活动建议：

1. 诗意时光：可以欣赏杜甫的《春夜喜雨》，感受"好雨知时节，当春乃发生"的意境
2. 散步放松：初夏傍晚的微风特别舒适，适合在公园或河边散步
3. 音乐疗愈：听些轻音乐，让《Cloud》这样的钢琴曲带走一天的疲惫
4. 阅读充电：选本喜欢的书，泡杯茶享受独处时光
5. 朋友小聚：约上好友共进晚餐，分享今日趣事

