INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1921868836634759168, 1798176607609950208, '4nuygvmA6YFwObMzJwVqq', '根据分析结果，我对@大炮郭微博的第一印象如下：
