INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1922214613882114048, 1798176607609950208, 'nxWaL1Dosoh5XmdMm6Asi', '以下是整合了小红书风格设计和交互功能的完整静态页面HTML代码，您可以复制使用：

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>小红书风格社交网站</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <style>
        /* 自定义动画和样式 */
        @keyframes heartBeat {
            0% { transform: scale(1); }
            14% { transform: scale(1.3); }
            28% { transform: scale(1); }
            42% { transform: scale(1.3); }
            70% { transform: scale(1); }
        }
        .heart-animate {
            animation: heartBeat 1s;
        }
    </style>
</head>
<body class="bg-gray-50">
    <!-- 导航栏 -->
    <nav class="bg-red-500 text-white p-4 fixed w-full top-0 z-50 shadow-md">
        <div class="container mx-auto flex justify-between items-center">
            <div class="text-xl font-bold">小红书</div>
            <div class="flex space-x-4">
                <button class="hover:bg-red-600 px-3 py-1 rounded">首页</button>
                <button class="hover:bg-red-600 px-3 py-1 rounded">发现</button>
                <button class="hover:bg-red-600 px-3 py-1 rounded">消息</button>
                <button class="hover:bg-red-600 px-3 py-1 rounded">我</button>
            </div>
        </div>
    </nav>

    <!-- 主要内容区 -->
    <main class="container mx-auto mt-20 px-4 pb-16">
        <!-- 瀑布流内容 -->
        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6" id="content-grid">
            <!-- 内容卡片将通过JS动态生成 -->
        </div>
    </main>

    <!-- 悬浮发布按钮 -->
    <div class="fixed bottom-8 right-8">
        <button class="bg-red-500 text-white rounded-full p-4 shadow-lg hover:bg-red-600 transition">
            <svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4" />
            </svg>
        </button>
    </div>

    <script>
        // 示例数据
        const samplePosts = [
            {
                id: 1,
                user: {
                    name: "旅行达人",
                    avatar: "https://randomuser.me/api/portraits/women/44.jpg"
                },
                image: "https://picsum.photos/600/800?random=1",
                title: "三亚最美海滩推荐",
                likes: 124,
                comments: 32,
                isLiked: false
            },
            // 更多示例数据...
        ];

        // 初始化页面
        document.addEventListener(''DOMContentLoaded'', function() {
            const contentGrid = document.getElementById(''content-grid'');
            
            // 生成内容卡片
            samplePosts.forEach(post => {
                const card = document.createElement(''div'');
                card.className = ''bg-white rounded-lg overflow-hidden shadow-md hover:shadow-lg transition'';
                card.innerHTML = `
                    <img src="${post.image}" alt="${post.title}" class="w-full h-64 object-cover">
                    <div class="p-4">
                        <div class="flex items-center mb-2">
                            <img src="${post.user.avatar}" alt="${post.user.name}" class="w-8 h-8 rounded-full mr-2">
                            <span class="font-medium">${post.user.name}</span>
                        </div>
                        <h3 class="text-lg font-semibold mb-3">${post.title}</h3>
                        <div class="flex justify-between">
                            <button class="like-btn flex items-center ${post.isLiked ? ''text-red-500'' : ''text-gray-500''}" data-id="${post.id}">
                                <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-1" fill="${post.isLiked ? ''currentColor'' : ''none''}" viewBox="0 0 24 24" stroke="currentColor">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                                </svg>
                                <span>${post.likes}</span>
                            </button>
                            <button class="comment-btn flex items-center text-gray-500" data-id="${post.id}">
                                <svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395', 'f', '2025-05-13 16:57:31.627127', 'admin', '2025-05-13 17:10:17.146024', 'admin');
