INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1922854315937107968, 1798176607609950208, 'nxWaL1Dosoh5XmdMm6Asi', '马龙被称为"六边形战士"是因为日本媒体使用六边形雷达图来评估乒乓球选手的技术能力时，他在所有技术维度上都达到了近乎完美的表现。具体来说：

1. 技术维度包括：速度、力量、旋转、落点控制、战术应变、心态控制、发球、防守和经验等（不同来源略有差异，但核心是全面无短板）。

2. 马龙在这些维度的表现：
   - 关键分处理成功率高达82%
   - 比赛掌控力和临场应变能力超强
   - 各项技术指标都接近满分（5分制中全部达到5分）

3. 这个称号最早源于2016年吉隆坡世乒赛期间，日本媒体通过六边形雷达图对比显示马龙全面碾压日本选手（如吉村真晴某些维度只有2分）

4. "六边形战士"不仅体现了马龙技术的全面性，更象征着他作为乒乓球运动员的统治地位和超强综合实力，是乒乓球界对完美选手的形象化表述。', 'f', '2025-05-15 11:19:28.482374', 'admin', '2025-05-15 11:23:11.378805', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1922901091754840064, 1798176607609950208, 'nxWaL1Dosoh5XmdMm6Asi', '西安市未来一周的天气怎么样？', 't', '2025-05-15 14:25:20.703433', 'admin', '2025-05-15 14:25:20.703433', 'admin');
