INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1923279796322832384, 1798176607609950208, '4nuygvmA6YFwObMzJwVqq', '# 微博用户 @云来雁去 分析报告

