INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1923284120247603200, 1798176607609950208, 'QocaZjuFlSWf9tnEkWxfF', '《长安的荔枝》一书主要讲了什么故事？', 't', '2025-05-16 15:47:21.815083', 'admin', '2025-05-16 15:47:21.815083', 'admin');
INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1923284120276963328, 1798176607609950208, 'QocaZjuFlSWf9tnEkWxfF', '《长安的荔枝》讲述了唐朝天宝年间，长安城小吏李善德被迫接受一个看似不可能完成的任务：在贵妃生日前，将五千余里外岭南的新鲜荔枝运到长安。由于荔枝保鲜期仅三天，李善德凭借智慧历尽艰险完成任务，同时揭露了官场的腐败荒唐。小说通过这个小人物视角，生动展现了盛唐时期的社会风貌和官场生态。', 'f', '2025-05-16 15:47:21.822217', 'admin', '2025-05-16 15:48:16.992249', 'admin');
