INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1927588455127322624, 1798176607609950208, 'e-StW30mk8v4CbXy3XhKV', '### 🍽️ 两人晚餐推荐（5月末时令版）

