INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1924319045813932032, 1798176607609950208, 'trvfTfKy4vAl8OAneIslO', '"宫廷玉液酒"的下一句是"一百八一杯"。这是1996年央视春晚小品《打工奇遇》中赵丽蓉老师的经典台词，讲述揭露商家虚假宣传的故事，已经成为中国家喻户晓的文化记忆。', 'f', '2025-05-19 12:19:47.297758', 'admin', '2025-05-19 12:21:55.022964', 'admin');
