INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1924397620382535680, 1798176607609950208, 'e-StW30mk8v4CbXy3XhKV', '马龙被称为"六边形战士"是因为日本权威媒体《东京乒乓球新闻》使用六维雷达图评估乒乓球选手实力时，他在力量、速度、技巧、发球、防守和经验这六个方面的能力值都达到了最高水平，形成了一个完美的六边形。这个称号形象地展现了马龙在乒乓球领域的全面卓越实力，说明他在所有技术环节都达到了顶尖水平，几乎没有短板。', 'f', '2025-05-19 17:32:00.934804', 'admin', '2025-05-19 17:33:47.913328', 'admin');
