INSERT INTO "chat_messages" ("id", "app_id", "conversation_id", "content", "is_user_message", "created_at", "created_by", "updated_at", "updated_by") VALUES (1925852364145823744, 1798176607609950208, 'BbP97mHViIIsi5jVSEuvP', '已成功在浏览器中打开事故报告表单页面，部署的URL为：https://mcp.edgeone.site/share/lWFH0SLgPr477cN5zlNXP

